/**
 * PostCSS plugin to generate sRGB / RGBA fallbacks for modern CSS color functions
 * (oklch and color-mix) generated by Tailwind CSS v4.
 *
 * This ensures full backward compatibility with older kiosk browsers and legacy PCs
 * (e.g. Chrome < 111, Windows 7/8/10 kiosk builds, Safari < 16.4, Firefox < 128)
 * without losing wide-gamut capabilities on modern browsers.
 */

function hexToRgb(hex) {
  if (hex.length === 3) {
    return {
      r: parseInt(hex[0] + hex[0], 16),
      g: parseInt(hex[1] + hex[1], 16),
      b: parseInt(hex[2] + hex[2], 16),
    };
  }
  return {
    r: parseInt(hex.substring(0, 2), 16),
    g: parseInt(hex.substring(2, 4), 16),
    b: parseInt(hex.substring(4, 6), 16),
  };
}

function oklchToRgb(l, c, h, alpha = 1) {
  h = isNaN(h) ? 0 : h;
  const hRad = (h * Math.PI) / 180;
  const oklabA = c * Math.cos(hRad);
  const oklabB = c * Math.sin(hRad);

  const l_ = l + 0.3963377774 * oklabA + 0.2158037573 * oklabB;
  const m_ = l - 0.1055613458 * oklabA - 0.0638541728 * oklabB;
  const s_ = l - 0.0894841775 * oklabA - 1.2914855480 * oklabB;

  const l3 = l_ * l_ * l_;
  const m3 = m_ * m_ * m_;
  const s3 = s_ * s_ * s_;

  const rLinear = +4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3;
  const gLinear = -1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3;
  const bLinear = -0.0041960863 * l3 - 0.7034186147 * m3 + 1.7076147010 * s3;

  function toSrgb(val) {
    const clamped = Math.max(0, Math.min(1, val));
    const companded = clamped <= 0.0031308 ? 12.92 * clamped : 1.055 * Math.pow(clamped, 1 / 2.4) - 0.055;
    return Math.round(Math.max(0, Math.min(255, companded * 255)));
  }

  const r = toSrgb(rLinear);
  const g = toSrgb(gLinear);
  const b = toSrgb(bLinear);

  if (alpha < 1) {
    const aFormatted = Math.round(alpha * 1000) / 1000;
    return `rgba(${r}, ${g}, ${b}, ${aFormatted})`;
  }
  return `rgb(${r}, ${g}, ${b})`;
}

function parseOklchMatch(lStr, cStr, hStr, aStr) {
  const l = lStr.endsWith('%') ? parseFloat(lStr) / 100 : parseFloat(lStr);
  const c = cStr === 'none' ? 0 : parseFloat(cStr);
  const h = hStr === 'none' ? 0 : parseFloat(hStr);
  let alpha = 1;
  if (aStr) {
    alpha = aStr.endsWith('%') ? parseFloat(aStr) / 100 : parseFloat(aStr);
  }
  return oklchToRgb(l, c, h, alpha);
}

function replaceColorMix(value) {
  // Pattern 1: color-mix(in srgb, #hex <pct>%, transparent)
  const cmHex1 = /color-mix\(\s*in\s+srgb\s*,\s*#([0-9a-fA-F]{3,8})\s+(\d+(?:\.\d+)?)%\s*,\s*transparent\s*\)/gi;
  value = value.replace(cmHex1, (_, hex, pct) => {
    const { r, g, b } = hexToRgb(hex);
    const a = Math.round((parseFloat(pct) / 100) * 1000) / 1000;
    return `rgba(${r}, ${g}, ${b}, ${a})`;
  });

  // Pattern 2: color-mix(in srgb, transparent <pct>%, #hex)
  const cmHex2 = /color-mix\(\s*in\s+srgb\s*,\s*transparent\s+(\d+(?:\.\d+)?)%\s*,\s*#([0-9a-fA-F]{3,8})\s*\)/gi;
  value = value.replace(cmHex2, (_, pct, hex) => {
    const { r, g, b } = hexToRgb(hex);
    const a = Math.round((1 - parseFloat(pct) / 100) * 1000) / 1000;
    return `rgba(${r}, ${g}, ${b}, ${a})`;
  });

  // Pattern 3: color-mix(in srgb, oklch(...) <pct>%, transparent)
  const cmOklch1 = /color-mix\(\s*in\s+srgb\s*,\s*oklch\(\s*([\d.]+%?)\s+([\d.]+|none)\s+([\d.]+|none)(?:\s*\/\s*([\d.]+%?))?\s*\)\s+(\d+(?:\.\d+)?)%\s*,\s*transparent\s*\)/gi;
  value = value.replace(cmOklch1, (_, lStr, cStr, hStr, baseAlphaStr, pct) => {
    let baseAlpha = 1;
    if (baseAlphaStr) {
      baseAlpha = baseAlphaStr.endsWith('%') ? parseFloat(baseAlphaStr) / 100 : parseFloat(baseAlphaStr);
    }
    const mixAlpha = parseFloat(pct) / 100;
    const finalAlpha = Math.round(baseAlpha * mixAlpha * 1000) / 1000;
    return parseOklchMatch(lStr, cStr, hStr, `${finalAlpha}`);
  });

  // Pattern 4: color-mix(in srgb, transparent <pct>%, oklch(...))
  const cmOklch2 = /color-mix\(\s*in\s+srgb\s*,\s*transparent\s+(\d+(?:\.\d+)?)%\s*,\s*oklch\(\s*([\d.]+%?)\s+([\d.]+|none)\s+([\d.]+|none)(?:\s*\/\s*([\d.]+%?))?\s*\)\s*\)/gi;
  value = value.replace(cmOklch2, (_, pct, lStr, cStr, hStr, baseAlphaStr) => {
    let baseAlpha = 1;
    if (baseAlphaStr) {
      baseAlpha = baseAlphaStr.endsWith('%') ? parseFloat(baseAlphaStr) / 100 : parseFloat(baseAlphaStr);
    }
    const mixAlpha = 1 - parseFloat(pct) / 100;
    const finalAlpha = Math.round(baseAlpha * mixAlpha * 1000) / 1000;
    return parseOklchMatch(lStr, cStr, hStr, `${finalAlpha}`);
  });

  return value;
}

function replaceOklch(value) {
  const oklchRegex = /oklch\(\s*([\d.]+%?)\s+([\d.]+|none)\s+([\d.]+|none)(?:\s*\/\s*([\d.]+%?))?\s*\)/gi;
  return value.replace(oklchRegex, (_, lStr, cStr, hStr, aStr) => {
    return parseOklchMatch(lStr, cStr, hStr, aStr);
  });
}

function isInsideColorMixSupports(decl) {
  let cur = decl.parent;
  while (cur) {
    if (cur.type === 'atrule' && cur.name === 'supports' && cur.params && cur.params.includes('color-mix')) {
      return true;
    }
    cur = cur.parent;
  }
  return false;
}

export default function legacyColorFallback() {
  return {
    postcssPlugin: 'postcss-legacy-color-fallback',
    Declaration(decl) {
      if (!decl.value) return;
      if (isInsideColorMixSupports(decl)) return;

      const val = decl.value;
      if (!val.includes('color-mix') && !val.includes('oklch')) return;

      const fallback = replaceOklch(replaceColorMix(val));
      if (fallback !== val) {
        decl.cloneBefore({ value: fallback });
      }
    },
  };
}
legacyColorFallback.postcss = true;
